 $('reportStudentSearch').onchange=async()=>{const q=$('reportStudentSearch').value.trim(),s=students.find(x=>(x.name+' · '+x.employee_id).toLowerCase()===q.toLowerCase()||x.name.toLowerCase()===q.toLowerCase()||x.employee_id.toLowerCase()===q.toLowerCase());if(!s){$('reportStudent').value='';$('individualReport').innerHTML='';return}$('reportStudent').value=s.id;const y=Number($('reportYear').value),m=Number($('reportMonth').value),{data,error}=await sb.from('attendance').select('attendance_date,status').eq('student_id',s.id).gte('attendance_date',y+'-01-01').lte('attendance_date',y+'-12-31');if(error){$('individualReport').textContent=error.message;return}const list=data||[],p=list.filter(x=>x.status==='present').length,a=list.filter(x=>x.status==='absent').length,{data:hols}=await sb.from('holidays').select('holiday_date').gte('holiday_date',y+'-01-01').lte('holiday_date',y+'-12-31'),holidaySet=new Set((hols||[]).map(x=>x.holiday_date)),holidayCount=[...holidaySet].filter(dt=>(!s.joining_date||dt>=s.joining_date)&&(!s.left_date||dt<=s.left_date)).length,notMarked=Math.max(0,daysInYear(y,s)-holidayCount-p-a),total=p+a,monthPrefix=y+'-'+String(m).padStart(2,'0'),monthRows=list.filter(x=>x.attendance_date.startsWith(monthPrefix)),mp=monthRows.filter(x=>x.status==='present').length,ma=monthRows.filter(x=>x.status==='absent').length,monthDays=new Date(y,m,0).getDate(),monthEligible=Array.from({length:monthDays},(_,i)=>monthPrefix+'-'+String(i+1).padStart(2,'0')).filter(dt=>(!s.joining_date||dt>=s.joining_date)&&(!s.left_date||dt<=s.left_date)&&!holidaySet.has(dt)).length,monthMissing=Math.max(0,monthEligible-mp-ma),first=new Date(y,m-1,1).getDay(),cells=Array(first).fill('<span class="calendar-empty"></span>'),byDate=new Map(list.map(x=>[x.attendance_date,x.status]));for(let d=1;d<=monthDays;d++){const dt=monthPrefix+'-'+String(d).padStart(2,'0'),status=byDate.get(dt),holiday=holidaySet.has(dt),eligible=(!s.joining_date||dt>=s.joining_date)&&(!s.left_date||dt<=s.left_date);cells.push('<span class="calendar-day '+(holiday?'calendar-holiday':status==='present'?'cycle-present':status==='absent'?'cycle-absent':!eligible?'calendar-ineligible':'cycle-unmarked')+'"><b>'+d+'</b><small>'+(holiday?'Holiday':!eligible?'—':status||'Not marked')+'</small></span>')}$('individualReport').innerHTML='<h4>'+esc(s.name)+' · '+esc(s.employee_id)+'</h4><h4>Yearly summary · '+y+'</h4><div class="attendance-summary"><span>Present <strong>'+p+'</strong></span><span>Absent <strong>'+a+'</strong></span><span>Not marked <strong>'+notMarked+'</strong></span><span>Attendance <strong>'+(total?(p/total*100).toFixed(1):'0')+'%</strong></span></div>'+(notMarked?'<div class="notice">Some eligible dates have no attendance record.</div>':'')+'<h4>Monthly summary · '+new Date(y,m-1,1).toLocaleString(undefined,{month:'long'})+'</h4><div class="attendance-summary"><span>Present <strong>'+mp+'</strong></span><span>Absent <strong>'+ma+'</strong></span><span>Not marked <strong>'+monthMissing+'</strong></span><span>Attendance <strong>'+(mp+ma?(mp/(mp+ma)*100).toFixed(1):'0')+'%</strong></span></div><div class="calendar-weekdays">'+['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(x=>'<span>'+x+'</span>').join('')+'</div><div class="calendar-days">'+cells.join('')+'</div>';};
 function daysInYear(y,s){const start=new Date(y,0,1),end=new Date(y,11,31);if(s.joining_date&&s.joining_date>y+'-12-31'||s.left_date&&s.left_date<y+'-01-01')return 0;const from=s.joining_date&&s.joining_date>y+'-01-01'?new Date(s.joining_date+'T00:00:00'):start,to=s.left_date&&s.left_date<y+'-12-31'?new Date(s.left_date+'T00:00:00'):end;return Math.max(0,Math.floor((to-from)/86400000)+1);}
 function downloadDay(){const rows=[['Employee ID','Name','Date','Status'],...students.map(s=>[s.employee_id,s.name,$('attendanceDate').value,attendance[s.id]||'Not marked'])];const csv=rows.map(r=>r.map(x=>'"'+String(x).replace(/"/g,'""')+'"').join(',')).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download='NKKAMS_attendance_'+$('attendanceDate').value+'.csv';a.click();URL.revokeObjectURL(a.href)}


