 async function adminCall(action,body={}){const {data:{session}}=await sb.auth.getSession();if(!session)throw new Error('Your session expired. Sign in again.');const response=await fetch(cfg.url+'/functions/v1/admin-users',{method:'POST',headers:{'Content-Type':'application/json','apikey':cfg.publishableKey,'Authorization':'Bearer '+session.access_token},body:JSON.stringify({action,...body})});const result=await response.json();if(!response.ok)throw new Error(result.error||'The request failed.');return result}
