 async function loadContacts(){try{const result=await publicCall('public_admin_contacts');const html=(result.contacts||[]).map(c=>'<div class="contact-card"><strong>'+esc(c.name)+'</strong>'+(c.whatsapp?'<div>WhatsApp: <a href="https://wa.me/'+esc(c.whatsapp.replace(/[^0-9]/g,''))+'" target="_blank" rel="noopener">'+esc(c.whatsapp)+'</a></div>':'')+(c.email?'<div>Email: <a href="mailto:'+esc(c.email)+'">'+esc(c.email)+'</a></div>':'')+'</div>').join('')||'<p class="muted">No administrator contacts are available.</p>';$('adminContactList').innerHTML=html;if($('loginAdminContacts'))$('loginAdminContacts').innerHTML='<h3>Contact an administrator</h3>'+html}catch(e){$('adminContactList').textContent=e.message}}
